def compose_detailed_machine_with_exc_avr1(
        machine_template: RmsModelTemplate,
        exciter_template: RmsModelTemplate,
        avr1_parameters: ExcAVR1Parameters | None = None,
        avr2_parameters: ExcAVR2Parameters | None = None,
        avr3_parameters: ExcAVR3Parameters | None = None,
        avr7_parameters: ExcAVR7Parameters | None = None,
        cz_parameters: ExcCZParameters | None = None,
) -> RmsModelTemplate | None:
    """Bind supported voltage-regulator terminal voltage and Efd to a machine.

    :param machine_template: Equation-backed detailed machine graph.
    :param exciter_template: Standalone equation-backed ExcAVR1 graph.
    :param avr1_parameters: Canonical ExcAVR1 settings; omitted for other voltage models.
    :param avr2_parameters: Canonical ExcAVR2 settings; omitted for other voltage models.
    :param avr3_parameters: Canonical ExcAVR3 settings; omitted for other voltage models.
    :param avr7_parameters: Canonical ExcAVR7 settings; omitted for other voltage models.
    :param cz_parameters: Canonical ExcCZ settings; omitted for other voltage models.
    :return: Composite generator graph when required ports exist.
    """
    composite_name: str = f'{machine_template.name}_with_{exciter_template.name}'
    composite_template: RmsModelTemplate = RmsModelTemplate(name=composite_name)
    composite_template.tpe = machine_template.tpe
    composite_template.block = deepcopy(machine_template.block)
    composite_template.block.children.append(deepcopy(exciter_template.block))
    machine_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'Vm')
    machine_field_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'EfdPu')
    exciter_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'UsPu_{exciter_template.name}',
    )
    exciter_field_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'EfdPu_{exciter_template.name}',
    )
    if (
            machine_voltage is not None
            and machine_field_voltage is not None
            and exciter_voltage is not None
            and exciter_field_voltage is not None
    ):
        avr7_machine_field_voltage_initial: Expr | Const | None = None
        avr7_machine_voltage_initial: Expr | Const | None = None
        if avr7_parameters is not None:
            avr7_machine_field_voltage_initial = find_block_initial_value(
                composite_template.block,
                machine_field_voltage,
            )
            avr7_machine_voltage_initial = find_block_initial_value(
                composite_template.block,
                machine_voltage,
            )
            if avr7_machine_voltage_initial is None:
                avr7_machine_voltage_initial = machine_voltage
            else:
                pass
        else:
            pass
        connect_cgmes_runtime_blocks(
            block=composite_template.block,
            variables_to_substitute=[exciter_voltage, machine_field_voltage],
            incoming_variables=[machine_voltage, exciter_field_voltage],
        )
        if avr1_parameters is not None:
            machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_field_voltage,
            )
            machine_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_voltage,
            )
            if machine_field_voltage_initial is not None:
                field_saturation: Expr = get_ieee_ac_exciter_saturation(
                    field_state=machine_field_voltage_initial,
                    ve1=avr1_parameters.e1,
                    seve1=avr1_parameters.se1,
                    ve2=avr1_parameters.e2,
                    seve2=avr1_parameters.se2,
                )
                regulator_initial: Expr = sym.hard_sat(
                    field_saturation * machine_field_voltage_initial,
                    Const(avr1_parameters.vrmn),
                    Const(avr1_parameters.vrmx),
                )
                feedback_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'FeedbackMemoryPu_{exciter_template.name}',
                )
                regulator_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorMemoryPu_{exciter_template.name}',
                )
                regulator_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorOutputPu_{exciter_template.name}',
                )
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                reference_initial: Expr | Const | None = None
                if machine_voltage_initial is not None and avr1_parameters.ka != 0.0:
                    reference_initial = (
                        machine_voltage_initial + regulator_initial / Const(avr1_parameters.ka)
                    )
                else:
                    pass
                for runtime_block in composite_template.block.get_all_blocks():
                    if exciter_field_voltage in runtime_block.state_vars:
                        runtime_block.init_eqs[exciter_field_voltage] = machine_field_voltage_initial
                    else:
                        pass
                    if feedback_memory is not None and (
                            feedback_memory in runtime_block.state_vars
                            or feedback_memory in runtime_block.algebraic_vars
                    ):
                        runtime_block.init_eqs[feedback_memory] = machine_field_voltage_initial
                    else:
                        pass
                    if regulator_memory is not None and regulator_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[regulator_memory] = regulator_initial
                    else:
                        pass
                    if regulator_output is not None and regulator_output in runtime_block.algebraic_vars:
                        runtime_block.init_eqs[regulator_output] = regulator_initial
                    else:
                        pass
                    if (
                            reference_initial is not None
                            and reference is not None
                            and reference in runtime_block.in_vars
                    ):
                        runtime_block.init_eqs[reference] = reference_initial
                    else:
                        pass
            else:
                pass
        else:
            pass
        if avr2_parameters is not None:
            machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_field_voltage,
            )
            machine_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_voltage,
            )
            if machine_field_voltage_initial is not None:
                field_saturation: Expr = get_ieee_ac_exciter_saturation(
                    field_state=machine_field_voltage_initial,
                    ve1=avr2_parameters.e1,
                    seve1=avr2_parameters.se1,
                    ve2=avr2_parameters.e2,
                    seve2=avr2_parameters.se2,
                )
                regulator_initial: Expr = sym.hard_sat(
                    field_saturation * machine_field_voltage_initial,
                    Const(avr2_parameters.vrmn),
                    Const(avr2_parameters.vrmx),
                )
                feedback_input_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'FeedbackInputMemoryPu_{exciter_template.name}',
                )
                feedback_washout_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'FeedbackWashoutMemoryPu_{exciter_template.name}',
                )
                regulator_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorOutputPu_{exciter_template.name}',
                )
                regulator_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorMemoryPu_{exciter_template.name}',
                )
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                reference_initial: Expr | Const | None = None
                if machine_voltage_initial is not None and avr2_parameters.ka != 0.0:
                    reference_initial = (
                        machine_voltage_initial + regulator_initial / Const(avr2_parameters.ka)
                    )
                else:
                    pass
                for runtime_block in composite_template.block.get_all_blocks():
                    if exciter_field_voltage in runtime_block.state_vars:
                        runtime_block.init_eqs[exciter_field_voltage] = machine_field_voltage_initial
                    else:
                        pass
                    if feedback_input_memory is not None and feedback_input_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[feedback_input_memory] = regulator_initial
                    else:
                        pass
                    if feedback_washout_memory is not None and feedback_washout_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[feedback_washout_memory] = regulator_initial
                    else:
                        pass
                    if regulator_output is not None and regulator_output in runtime_block.algebraic_vars:
                        runtime_block.init_eqs[regulator_output] = regulator_initial
                    else:
                        pass
                    if regulator_memory is not None and regulator_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[regulator_memory] = regulator_initial
                    else:
                        pass
                    if (
                            reference_initial is not None
                            and reference is not None
                            and reference in runtime_block.in_vars
                    ):
                        runtime_block.init_eqs[reference] = reference_initial
                    else:
                        pass
            else:
                pass
        else:
            pass
        if avr3_parameters is not None:
            machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_field_voltage,
            )
            machine_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_voltage,
            )
            if machine_field_voltage_initial is not None:
                field_saturation: Expr = get_ieee_ac_exciter_saturation(
                    field_state=machine_field_voltage_initial,
                    ve1=avr3_parameters.e1,
                    seve1=avr3_parameters.se1,
                    ve2=avr3_parameters.e2,
                    seve2=avr3_parameters.se2,
                )
                regulator_initial: Expr = field_saturation * machine_field_voltage_initial
                first_stage_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'FirstStageMemoryPu_{exciter_template.name}',
                )
                second_stage_memory: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'SecondStageMemoryPu_{exciter_template.name}',
                )
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                reference_initial: Expr | Const | None = None
                if machine_voltage_initial is not None and avr3_parameters.ka != 0.0:
                    reference_initial = (
                        machine_voltage_initial + regulator_initial / Const(avr3_parameters.ka)
                    )
                else:
                    pass
                for runtime_block in composite_template.block.get_all_blocks():
                    if exciter_field_voltage in runtime_block.state_vars:
                        runtime_block.init_eqs[exciter_field_voltage] = machine_field_voltage_initial
                    else:
                        pass
                    if first_stage_memory is not None and first_stage_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[first_stage_memory] = regulator_initial
                    else:
                        pass
                    if second_stage_memory is not None and second_stage_memory in runtime_block.state_vars:
                        runtime_block.init_eqs[second_stage_memory] = regulator_initial
                    else:
                        pass
                    if (
                            reference_initial is not None
                            and reference is not None
                            and reference in runtime_block.in_vars
                    ):
                        runtime_block.init_eqs[reference] = reference_initial
                    else:
                        pass
            else:
                pass
        else:
            pass
        if avr7_parameters is not None:
            first_stage_gain: float = (
                avr7_parameters.k1 * avr7_parameters.a1 / avr7_parameters.a2
                if avr7_parameters.a2 != 0.0
                else 0.0
            )
            second_stage_gain: float = (
                avr7_parameters.k3 * avr7_parameters.a3 / avr7_parameters.a4
                if avr7_parameters.a4 != 0.0
                else 0.0
            )
            final_stage_gain: float = (
                avr7_parameters.k5 * avr7_parameters.a5 / avr7_parameters.a6
                if avr7_parameters.a6 != 0.0
                else 0.0
            )
            if (
                    avr7_machine_field_voltage_initial is not None
                    and avr7_machine_voltage_initial is not None
                    and avr7_parameters.a2 != 0.0
                    and avr7_parameters.a4 != 0.0
                    and avr7_parameters.a6 != 0.0
                    and first_stage_gain != 0.0
                    and second_stage_gain != 0.0
                    and final_stage_gain != 0.0
            ):
                second_output_initial: Expr = (
                    avr7_machine_field_voltage_initial / Const(final_stage_gain)
                )
                first_output_initial: Expr = (
                    second_output_initial / Const(second_stage_gain)
                )
                input_initial: Expr = first_output_initial / Const(first_stage_gain)
                first_memory_initial: Expr = input_initial / Const(avr7_parameters.a2)
                second_memory_initial: Expr = (
                    first_output_initial / Const(avr7_parameters.a4)
                )
                final_memory_initial: Expr = (
                    second_output_initial / Const(avr7_parameters.a6)
                )
                stage_initial_values: tuple[tuple[str, Expr], ...] = (
                    (f'FirstStageMemoryPu_{exciter_template.name}', first_memory_initial),
                    (f'SecondStageMemoryPu_{exciter_template.name}', second_memory_initial),
                    (f'FinalStageMemoryPu_{exciter_template.name}', final_memory_initial),
                    (f'FirstStageOutputPu_{exciter_template.name}', first_output_initial),
                    (f'SecondStageOutputPu_{exciter_template.name}', second_output_initial),
                    (f'FinalStageOutputPu_{exciter_template.name}', avr7_machine_field_voltage_initial),
                    (f'EfdPu_{exciter_template.name}', avr7_machine_field_voltage_initial),
                )
                reference_initial: Expr = avr7_machine_voltage_initial + input_initial
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                for runtime_block in composite_template.block.get_all_blocks():
                    for stage_name, stage_initial in stage_initial_values:
                        stage_variable: Var | None = find_block_variable_by_name(
                            runtime_block,
                            stage_name,
                        )
                        if stage_variable is not None and (
                                stage_variable in runtime_block.state_vars
                                or stage_variable in runtime_block.algebraic_vars
                        ):
                            runtime_block.init_eqs[stage_variable] = stage_initial
                        else:
                            pass
                    else:
                        pass
                    if reference is not None and reference in runtime_block.in_vars:
                        runtime_block.init_eqs[reference] = reference_initial
                    else:
                        pass
                else:
                    pass
            else:
                pass
        else:
            pass
        if cz_parameters is not None:
            machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_field_voltage,
            )
            machine_voltage_initial: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                machine_voltage,
            )
            if machine_field_voltage_initial is not None:
                amplifier_target: Expr = sym.hard_sat(
                    sym.safe_divide(
                        machine_field_voltage_initial,
                        Const(cz_parameters.ke),
                        Const(1e-9),
                    ),
                    Const(cz_parameters.vrmin),
                    Const(cz_parameters.vrmax),
                )
                regulator_target: Expr = sym.hard_sat(
                    sym.safe_divide(
                        amplifier_target,
                        Const(cz_parameters.ka),
                        Const(1e-9),
                    ),
                    Const(cz_parameters.vrmin),
                    Const(cz_parameters.vrmax),
                )
                integral_state: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'IntegralPu_{exciter_template.name}',
                )
                regulator_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorOutputPu_{exciter_template.name}',
                )
                amplifier_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'AmplifierPu_{exciter_template.name}',
                )
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                for runtime_block in composite_template.block.get_all_blocks():
                    if exciter_field_voltage in runtime_block.state_vars or (
                            exciter_field_voltage in runtime_block.algebraic_vars
                    ):
                        runtime_block.init_eqs[exciter_field_voltage] = machine_field_voltage_initial
                    else:
                        pass
                    if integral_state is not None and integral_state in runtime_block.state_vars:
                        runtime_block.init_eqs[integral_state] = regulator_target
                    else:
                        pass
                    if regulator_output is not None and regulator_output in runtime_block.algebraic_vars:
                        runtime_block.init_eqs[regulator_output] = regulator_target
                    else:
                        pass
                    if amplifier_output is not None and (
                            amplifier_output in runtime_block.state_vars
                            or amplifier_output in runtime_block.algebraic_vars
                    ):
                        runtime_block.init_eqs[amplifier_output] = amplifier_target
                    else:
                        pass
                    if (
                            machine_voltage_initial is not None
                            and reference is not None
                            and reference in runtime_block.in_vars
                    ):
                        runtime_block.init_eqs[reference] = machine_voltage_initial
                    else:
                        pass
            else:
                pass
        else:
            pass
        composite_template.comment = 'CGMES detailed synchronous machine with ExcAVR1.'
        return composite_template
    else:
        return None


def compose_detailed_machine_with_exc_avr45(
        machine_template: RmsModelTemplate,
        exciter_template: RmsModelTemplate,
        avr4_parameters: ExcAVR4Parameters | None = None,
        avr5_parameters: ExcAVR5Parameters | None = None,
) -> RmsModelTemplate | None:
    """Bind AVR4/AVR5 terminal voltage, field current and Efd to the machine.

    :param machine_template: Equation-backed detailed synchronous-machine graph.
    :param exciter_template: Equation-backed standalone ExcAVR4/ExcAVR5 graph.
    :param avr4_parameters: Canonical ExcAVR4 settings for operating-point initialization.
    :param avr5_parameters: Canonical ExcAVR5 settings; omitted for ExcAVR4.
    :return: Composite graph when all required machine and exciter ports exist.
    """
    composite_name: str = f'{machine_template.name}_with_{exciter_template.name}'
    composite_template: RmsModelTemplate = RmsModelTemplate(name=composite_name)
    composite_template.tpe = machine_template.tpe
    composite_template.block = deepcopy(machine_template.block)
    composite_template.block.children.append(deepcopy(exciter_template.block))
    machine_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'Vm')
    machine_field_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'EfdPu')
    machine_field_current: Var | None = find_block_variable_by_name(composite_template.block, 'IfdPu')
    exciter_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'UsPu_{exciter_template.name}',
    )
    exciter_field_current: Var | None = find_block_variable_by_name(
        composite_template.block, f'IfdPu_{exciter_template.name}',
    )
    exciter_field_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'EfdPu_{exciter_template.name}',
    )
    if (
            machine_voltage is not None
            and machine_field_voltage is not None
            and machine_field_current is not None
            and exciter_voltage is not None
            and exciter_field_current is not None
            and exciter_field_voltage is not None
    ):
        machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_field_voltage,
        )
        machine_field_current_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_field_current,
        )
        machine_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_voltage,
        )
        connect_cgmes_runtime_blocks(
            block=composite_template.block,
            variables_to_substitute=[
                exciter_voltage, exciter_field_current, machine_field_voltage,
            ],
            incoming_variables=[
                machine_voltage, machine_field_current, exciter_field_voltage,
            ],
        )
        if avr4_parameters is not None:
            if (
                    machine_field_voltage_initial is not None
                    and machine_field_current_initial is not None
                    and machine_voltage_initial is not None
            ):
                exciter_multiplier: Expr | Const = (
                    machine_voltage_initial if avr4_parameters.imul else Const(1.0)
                )
                exciter_output_target: Expr = sym.safe_divide(
                    machine_field_voltage_initial,
                    exciter_multiplier,
                    Const(0.0),
                )
                if avr4_parameters.ke == 0.0:
                    exciter_input_target: Expr = Const(0.0)
                else:
                    limited_exciter_output_target: Expr = sym.hard_sat(
                        exciter_output_target,
                        Const(avr4_parameters.vfmn),
                        Const(avr4_parameters.vfmx),
                    )
                    exciter_input_target = sym.safe_divide(
                        limited_exciter_output_target,
                        Const(avr4_parameters.ke),
                        Const(0.0),
                    )
                if avr4_parameters.ka == 0.0:
                    regulator_target: Expr = Const(0.0)
                else:
                    regulator_target = exciter_input_target
                voltage_reference: Expr | Const = machine_voltage_initial
                if avr4_parameters.ka != 0.0:
                    voltage_reference = machine_voltage_initial + regulator_target / Const(
                        avr4_parameters.ka,
                    )
                else:
                    pass
                initialization_values: tuple[tuple[str, Expr | Const], ...] = (
                    (f'FirstStageMemoryPu_{exciter_template.name}', regulator_target),
                    (f'SecondStageMemoryPu_{exciter_template.name}', regulator_target),
                    (f'UpperCurrentMemoryPu_{exciter_template.name}', machine_field_current_initial),
                    (f'LowerCurrentMemoryPu_{exciter_template.name}', machine_field_current_initial),
                    (
                        f'ExciterOutputPu_{exciter_template.name}',
                        sym.hard_sat(
                            Const(avr4_parameters.ke) * regulator_target,
                            Const(avr4_parameters.vfmn),
                            Const(avr4_parameters.vfmx),
                        ),
                    ),
                    (f'EfdPu_{exciter_template.name}', machine_field_voltage_initial),
                    (f'UsRefPu_{exciter_template.name}', voltage_reference),
                )
                for runtime_block in composite_template.block.get_all_blocks():
                    for variable_name, initial_value in initialization_values:
                        initial_variable: Var | None = find_block_variable_by_name(
                            runtime_block,
                            variable_name,
                        )
                        if initial_variable is not None and (
                                initial_variable in runtime_block.state_vars
                                or initial_variable in runtime_block.algebraic_vars
                                or initial_variable in runtime_block.in_vars
                                or initial_variable in runtime_block.out_vars
                        ):
                            runtime_block.init_eqs[initial_variable] = initial_value
                        else:
                            pass
                    else:
                        pass
                else:
                    pass
            else:
                pass
        elif avr5_parameters is not None:
            if machine_voltage_initial is None:
                machine_voltage_initial = machine_voltage
            else:
                pass
            if (
                    machine_field_voltage_initial is not None
                    and machine_field_current_initial is not None
                    and machine_voltage_initial is not None
            ):
                regulator_initial: Expr = (
                    machine_field_voltage_initial
                    + Const(avr5_parameters.rex) * machine_field_current_initial
                )
                reference_initial: Expr | Const = machine_voltage_initial
                if avr5_parameters.ka != 0.0:
                    reference_initial = (
                        machine_voltage_initial
                        + regulator_initial / Const(avr5_parameters.ka)
                    )
                else:
                    pass
                regulator_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'RegulatorPu_{exciter_template.name}',
                )
                exciter_field_output: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'EfdPu_{exciter_template.name}',
                )
                reference: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'UsRefPu_{exciter_template.name}',
                )
                for runtime_block in composite_template.block.get_all_blocks():
                    if regulator_output is not None and (
                            regulator_output in runtime_block.state_vars
                            or regulator_output in runtime_block.algebraic_vars
                    ):
                        runtime_block.init_eqs[regulator_output] = regulator_initial
                    else:
                        pass
                    if exciter_field_output is not None and exciter_field_output in runtime_block.algebraic_vars:
                        runtime_block.init_eqs[exciter_field_output] = machine_field_voltage_initial
                    else:
                        pass
                    if reference is not None and reference in runtime_block.in_vars:
                        runtime_block.init_eqs[reference] = reference_initial
                    else:
                        pass
                else:
                    pass
            else:
                pass
        else:
            pass
        composite_template.comment = (
            f'CGMES detailed synchronous machine with {exciter_template.name}; '
            'terminal voltage, field current, and field voltage are connected.'
        )
        return composite_template
    else:
        return None


def compose_detailed_machine_with_exc_bbc(
        machine_template: RmsModelTemplate,
        exciter_template: RmsModelTemplate,
        parameters: ExcBBCParameters | None = None,
) -> RmsModelTemplate | None:
    """Bind ExcBBC voltage, field-current, and field-voltage machine ports.

    :param machine_template: Equation-backed detailed synchronous-machine graph.
    :param exciter_template: Equation-backed standalone ExcBBC graph.
    :param parameters: Canonical ExcBBC values used for operating-point initialization.
    :return: Composite graph when the detailed machine exposes all required ports.
    """
    composite_name: str = f'{machine_template.name}_with_{exciter_template.name}'
    composite_template: RmsModelTemplate = RmsModelTemplate(name=composite_name)
    composite_template.tpe = machine_template.tpe
    composite_template.block = deepcopy(machine_template.block)
    composite_template.block.children.append(deepcopy(exciter_template.block))
    machine_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'Vm')
    machine_field_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'EfdPu')
    machine_field_current: Var | None = find_block_variable_by_name(composite_template.block, 'IfdPu')
    machine_voltage_initial: Expr | Const | None = None
    machine_field_voltage_initial: Expr | Const | None = None
    machine_field_current_initial: Expr | Const | None = None
    if machine_voltage is not None:
        machine_voltage_initial = find_block_initial_value(composite_template.block, machine_voltage)
    else:
        pass
    if machine_field_voltage is not None:
        machine_field_voltage_initial = find_block_initial_value(
            composite_template.block,
            machine_field_voltage,
        )
    else:
        pass
    if machine_field_current is not None:
        machine_field_current_initial = find_block_initial_value(
            composite_template.block,
            machine_field_current,
        )
    else:
        pass
    exciter_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'UsPu_{exciter_template.name}',
    )
    exciter_field_current: Var | None = find_block_variable_by_name(
        composite_template.block, f'IfdPu_{exciter_template.name}',
    )
    exciter_field_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'EfdPu_{exciter_template.name}',
    )
    if (
            machine_voltage is not None
            and machine_field_voltage is not None
            and machine_field_current is not None
            and exciter_voltage is not None
            and exciter_field_current is not None
            and exciter_field_voltage is not None
    ):
        connect_cgmes_runtime_blocks(
            block=composite_template.block,
            variables_to_substitute=[exciter_voltage, exciter_field_current, machine_field_voltage],
            incoming_variables=[machine_voltage, machine_field_current, exciter_field_voltage],
        )
        if (
                parameters is not None
                and machine_voltage_initial is not None
                and machine_field_voltage_initial is not None
                and machine_field_current_initial is not None
        ):
            regulator_initial: Expr = sym.hard_sat(
                machine_field_voltage_initial
                + Const(parameters.xe) * machine_field_current_initial,
                Const(parameters.vrmin),
                Const(parameters.vrmax),
            )
            reference_initial: Expr | Const = machine_voltage_initial
            compensated_error_initial: Expr | Const = Const(0.0)
            if parameters.k != 0.0:
                compensated_error_initial = regulator_initial / Const(parameters.k)
                reference_initial = machine_voltage_initial + compensated_error_initial
            else:
                pass
            regulator_output: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'RegulatorOutputPu_{exciter_template.name}',
            )
            regulator_feedback: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'RegulatorFeedbackPu_{exciter_template.name}',
            )
            voltage_compensator: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'VoltageCompensatorPu_{exciter_template.name}',
            )
            voltage_compensator_state: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'VoltageCompensatorPuState_{exciter_template.name}',
            )
            exciter_reference: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'UsRefPu_{exciter_template.name}',
            )
            for runtime_block in composite_template.block.get_all_blocks():
                if regulator_output is not None and regulator_output in runtime_block.algebraic_vars:
                    runtime_block.init_eqs[regulator_output] = regulator_initial
                else:
                    pass
                if regulator_feedback is not None and regulator_feedback in runtime_block.state_vars:
                    runtime_block.init_eqs[regulator_feedback] = regulator_initial
                else:
                    pass
                if (
                        voltage_compensator is not None
                        and voltage_compensator in runtime_block.algebraic_vars
                ):
                    runtime_block.init_eqs[voltage_compensator] = compensated_error_initial
                else:
                    pass
                if (
                        voltage_compensator_state is not None
                        and voltage_compensator_state in runtime_block.state_vars
                ):
                    runtime_block.init_eqs[voltage_compensator_state] = compensated_error_initial
                else:
                    pass
                if exciter_field_voltage in runtime_block.algebraic_vars:
                    runtime_block.init_eqs[exciter_field_voltage] = machine_field_voltage_initial
                else:
                    pass
                if exciter_reference is not None and exciter_reference in runtime_block.in_vars:
                    runtime_block.init_eqs[exciter_reference] = reference_initial
                else:
                    pass
        else:
            pass
        composite_template.comment = 'CGMES detailed synchronous machine with ExcBBC.'
        return composite_template
    else:
        return None


def compose_detailed_machine_with_exc_dc(
        machine_template: RmsModelTemplate,
        exciter_template: RmsModelTemplate,
        dc_parameters: ExcDC1AParameters | ExcDC2AParameters | ExcDC3AParameters | None = None,
) -> RmsModelTemplate | None:
    """Bind DC exciter voltage, field voltage, and optional rotor speed to its machine.

    :param machine_template: Equation-backed detailed synchronous-machine graph.
    :param exciter_template: Equation-backed standalone DC excitation graph.
    :param dc_parameters: DC1A/DC2A/DC3A settings for sourced operating-point initialization.
    :return: Composite graph when each exposed exciter port has a machine signal.
    """
    composite_name: str = f'{machine_template.name}_with_{exciter_template.name}'
    composite_template: RmsModelTemplate = RmsModelTemplate(name=composite_name)
    composite_template.tpe = machine_template.tpe
    composite_template.block = deepcopy(machine_template.block)
    composite_template.block.children.append(deepcopy(exciter_template.block))
    machine_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'Vm')
    machine_field_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'EfdPu')
    exciter_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'UsPu_{exciter_template.name}',
    )
    exciter_field_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'EfdPu_{exciter_template.name}',
    )
    exciter_speed: Var | None = find_block_variable_by_name(
        composite_template.block, f'OmegaPu_{exciter_template.name}',
    )
    if (
            machine_voltage is not None
            and machine_field_voltage is not None
            and exciter_voltage is not None
            and exciter_field_voltage is not None
    ):
        machine_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_voltage,
        )
        machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_field_voltage,
        )
        if machine_voltage_initial is None:
            machine_voltage_initial = machine_voltage
        else:
            pass
        machine_speed: Var | None = None
        machine_speed_initial: Expr | Const | None = None
        if dc_parameters is not None and dc_parameters.ks != 0.0:
            machine_speed = find_block_variable_by_name(composite_template.block, 'omega')
            if machine_speed is not None:
                machine_speed_initial = find_block_initial_value(
                    composite_template.block,
                    machine_speed,
                )
                if machine_speed_initial is None:
                    machine_speed_initial = machine_speed
                else:
                    pass
            else:
                pass
        else:
            pass
        substitute_variables: List[Var] = list((exciter_voltage, machine_field_voltage))
        incoming_variables: List[Var] = list((machine_voltage, exciter_field_voltage))
        if exciter_speed is not None:
            machine_speed: Var | None = find_block_variable_by_name(composite_template.block, 'omega')
            if machine_speed is None:
                return None
            else:
                substitute_variables.append(exciter_speed)
                incoming_variables.append(machine_speed)
        else:
            pass
        connect_cgmes_runtime_blocks(
            block=composite_template.block,
            variables_to_substitute=substitute_variables,
            incoming_variables=incoming_variables,
        )
        if (
                dc_parameters is not None
                and machine_voltage_initial is not None
                and machine_field_voltage_initial is not None
        ):
            field_state_initial: Expr | Const = machine_field_voltage_initial
            if dc_parameters.ks != 0.0 and machine_speed_initial is not None:
                speed_multiplier: Expr = (
                    Const(1.0)
                    + Const(dc_parameters.ks) * (machine_speed_initial - Const(1.0))
                )
                field_state_initial = sym.safe_divide(
                    machine_field_voltage_initial,
                    speed_multiplier,
                    Const(1e-9),
                )
            else:
                pass
            saturation_exponent: float = math.log(
                dc_parameters.seefd2 / dc_parameters.seefd1,
            ) / (dc_parameters.efd2 - dc_parameters.efd1)
            saturation_scale: float = dc_parameters.seefd1 * math.exp(
                -saturation_exponent * dc_parameters.efd1,
            )
            saturation_initial: Expr = Const(saturation_scale) * sym.exp(
                Const(saturation_exponent) * field_state_initial,
            )
            zero_ke_calibration: bool = (
                isinstance(dc_parameters, ExcDC2AParameters)
                and dc_parameters.ke == 0.0
            )
            if zero_ke_calibration:
                effective_ke_variable: Var | None = find_block_variable_by_name(
                    composite_template.block,
                    f'KE_{exciter_template.name}',
                )
                effective_ke: Expr = -saturation_initial
                regulator_target: Expr = Const(0.0)
            else:
                effective_ke_variable = None
                effective_ke = Const(dc_parameters.ke)
                regulator_target = (effective_ke + saturation_initial) * field_state_initial
            field_state: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'ExciterVoltagePu_{exciter_template.name}',
            )
            regulator_output: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'RegulatorOutputPu_{exciter_template.name}',
            )
            rheostat_memory: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'RheostatPu_{exciter_template.name}',
            )
            voltage_reference: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'UsRefPu_{exciter_template.name}',
            )
            supplementary_input: Var | None = find_block_variable_by_name(
                composite_template.block,
                f'UpssPu_{exciter_template.name}',
            )
            supplementary_initial: Expr | Const = Const(0.0)
            if supplementary_input is not None:
                resolved_supplementary_initial: Expr | Const | None = find_block_initial_value(
                    composite_template.block,
                    supplementary_input,
                )
                if resolved_supplementary_initial is not None:
                    supplementary_initial = resolved_supplementary_initial
                else:
                    pass
            else:
                pass
            if isinstance(dc_parameters, ExcDC3AParameters):
                voltage_reference_initial: Expr | Const = (
                    machine_voltage_initial - supplementary_initial
                )
            else:
                if dc_parameters.ka != 0.0:
                    voltage_reference_initial = (
                        machine_voltage_initial
                        - supplementary_initial
                        + regulator_target / Const(dc_parameters.ka)
                    )
                else:
                    voltage_reference_initial = machine_voltage_initial - supplementary_initial
            exciter_field_voltage_initial: Expr | Const = machine_field_voltage_initial
            for runtime_block in composite_template.block.get_all_blocks():
                if effective_ke_variable is not None and effective_ke_variable in runtime_block.event_dict:
                    # Runtime initialization calibrates Ke; the parsed RDF Ke remains unchanged.
                    runtime_block.event_dict[effective_ke_variable] = effective_ke
                else:
                    pass
                if field_state is not None and field_state in runtime_block.state_vars:
                    runtime_block.init_eqs[field_state] = field_state_initial
                else:
                    pass
                if regulator_output is not None and (
                        regulator_output in runtime_block.state_vars
                        or regulator_output in runtime_block.algebraic_vars
                ):
                    runtime_block.init_eqs[regulator_output] = regulator_target
                else:
                    pass
                if (
                        rheostat_memory is not None
                        and rheostat_memory in runtime_block.state_vars
                ):
                    runtime_block.init_eqs[rheostat_memory] = sym.hard_sat(
                        regulator_target,
                        Const(dc_parameters.vrmin),
                        Const(dc_parameters.vrmax),
                    )
                else:
                    pass
                if (
                        exciter_field_voltage is not None
                        and exciter_field_voltage in runtime_block.algebraic_vars
                ):
                    runtime_block.init_eqs[exciter_field_voltage] = exciter_field_voltage_initial
                else:
                    pass
                if (
                        voltage_reference is not None
                        and voltage_reference in runtime_block.in_vars
                ):
                    runtime_block.init_eqs[voltage_reference] = voltage_reference_initial
                else:
                    pass
                for feedback_name in (
                        f'FeedbackFilterPu_{exciter_template.name}',
                        f'FeedbackLagPu_{exciter_template.name}',
                        f'FeedbackWashoutPu_{exciter_template.name}',
                ):
                    feedback_state: Var | None = find_block_variable_by_name(
                        runtime_block,
                        feedback_name,
                    )
                    if feedback_state is not None and feedback_state in runtime_block.state_vars:
                        runtime_block.init_eqs[feedback_state] = field_state_initial
                    else:
                        pass
                else:
                    pass
            else:
                pass
        else:
            pass
        return composite_template
    else:
        return None


def compose_detailed_machine_with_exc_dc3a1(
        machine_template: RmsModelTemplate,
        exciter_template: RmsModelTemplate,
        parameters: ExcDC3A1Parameters,
) -> RmsModelTemplate | None:
    """Bind DC3A1 terminal voltage, terminal current, field current, and Efd.

    :param machine_template: Detailed synchronous-machine equation graph.
    :param exciter_template: Equation-backed DC3A1 graph.
    :param parameters: Canonical bridge, regulator, and exciter settings.
    :return: Composite graph when all four machine ports exist.
    """
    composite_name: str = f'{machine_template.name}_with_{exciter_template.name}'
    composite_template: RmsModelTemplate = RmsModelTemplate(name=composite_name)
    composite_template.tpe = machine_template.tpe
    composite_template.block = deepcopy(machine_template.block)
    composite_template.block.children.append(deepcopy(exciter_template.block))
    machine_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'Vm')
    machine_terminal_current: Var | None = find_block_variable_by_name(composite_template.block, 'ItPu')
    machine_field_current: Var | None = find_block_variable_by_name(composite_template.block, 'IfdPu')
    machine_field_voltage: Var | None = find_block_variable_by_name(composite_template.block, 'EfdPu')
    exciter_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'UsPu_{exciter_template.name}',
    )
    exciter_terminal_current: Var | None = find_block_variable_by_name(
        composite_template.block, f'ItPu_{exciter_template.name}',
    )
    exciter_field_current: Var | None = find_block_variable_by_name(
        composite_template.block, f'IfdPu_{exciter_template.name}',
    )
    exciter_field_voltage: Var | None = find_block_variable_by_name(
        composite_template.block, f'EfdPu_{exciter_template.name}',
    )
    if (
            machine_voltage is not None
            and machine_terminal_current is not None
            and machine_field_current is not None
            and machine_field_voltage is not None
            and exciter_voltage is not None
            and exciter_terminal_current is not None
            and exciter_field_current is not None
            and exciter_field_voltage is not None
    ):
        machine_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_voltage,
        )
        machine_current_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_terminal_current,
        )
        machine_field_current_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_field_current,
        )
        machine_field_voltage_initial: Expr | Const | None = find_block_initial_value(
            composite_template.block,
            machine_field_voltage,
        )
        if machine_voltage_initial is None:
            machine_voltage_initial = machine_voltage
        else:
            pass
        if machine_current_initial is None:
            machine_current_initial = machine_terminal_current
        else:
            pass
        if machine_field_current_initial is None:
            machine_field_current_initial = machine_field_current
        else:
            pass
        if machine_field_voltage_initial is None:
            machine_field_voltage_initial = machine_field_voltage
        else:
            pass
        connect_cgmes_runtime_blocks(
            block=composite_template.block,
            variables_to_substitute=list((exciter_voltage, exciter_terminal_current,
                                          exciter_field_current, machine_field_voltage)),
            incoming_variables=list((machine_voltage, machine_terminal_current,
                                     machine_field_current, exciter_field_voltage)),
        )
        potential_magnitude: Expr = sym.sqrt(
            (Const(parameters.kp) * machine_voltage_initial) ** Const(2.0)
            + (Const(parameters.ki) * machine_current_initial) ** Const(2.0),
        )
        bridge_radicand: Expr = potential_magnitude ** Const(2.0) - (
            Const(0.78) * machine_field_current_initial
        ) ** Const(2.0)
        bridge_voltage: Expr = sym.hard_sat(
            sym.sqrt(sym.max(bridge_radicand, Const(0.0))),
            Const(0.0),
            Const(parameters.vb1max),
        )
        regulator_target: Expr = Const(parameters.ke) * machine_field_voltage_initial - bridge_voltage
        exciter_state: Var | None = None
        for runtime_block in composite_template.block.get_all_blocks():
            for state_variable in runtime_block.state_vars:
                if state_variable.name == f'EfdPu_{exciter_template.name}':
                    exciter_state = state_variable
                else:
                    pass
            else:
                pass
        else:
            pass
        exciter_output: Var | None = find_block_variable_by_name(
            composite_template.block,
            f'EfdPu_{exciter_template.name}',
        )
        regulator_output: Var | None = find_block_variable_by_name(
            composite_template.block,
            f'RegulatorOutputPu_{exciter_template.name}',
        )
        feedback_state: Var | None = find_block_variable_by_name(
            composite_template.block,
            f'FeedbackPu_{exciter_template.name}',
        )
        reference: Var | None = find_block_variable_by_name(
            composite_template.block,
            f'UsRefPu_{exciter_template.name}',
        )
        supplementary: Var | None = find_block_variable_by_name(
            composite_template.block,
            f'UpssPu_{exciter_template.name}',
        )
        supplementary_initial: Expr | Const = Const(0.0)
        if supplementary is not None:
            supplementary_value: Expr | Const | None = find_block_initial_value(
                composite_template.block,
                supplementary,
            )
            if supplementary_value is not None:
                supplementary_initial = supplementary_value
            else:
                pass
        else:
            pass
        if parameters.ka != 0.0:
            reference_initial: Expr | Const = (
                machine_voltage_initial
                - supplementary_initial
                - Const(parameters.kf) * machine_field_voltage_initial
                + regulator_target / Const(parameters.ka)
            )
        else:
            reference_initial = (
                machine_voltage_initial
                - supplementary_initial
                - Const(parameters.kf) * machine_field_voltage_initial
            )
        for runtime_block in composite_template.block.get_all_blocks():
            if exciter_state is not None and exciter_state in runtime_block.state_vars:
                runtime_block.init_eqs[exciter_state] = machine_field_voltage_initial
            else:
                pass
            if exciter_output is not None and exciter_output in runtime_block.algebraic_vars:
                runtime_block.init_eqs[exciter_output] = machine_field_voltage_initial
            else:
                pass
            if regulator_output is not None and (
                    regulator_output in runtime_block.state_vars
                    or regulator_output in runtime_block.algebraic_vars
            ):
                runtime_block.init_eqs[regulator_output] = regulator_target
            else:
                pass
            if feedback_state is not None and feedback_state in runtime_block.state_vars:
                runtime_block.init_eqs[feedback_state] = machine_field_voltage_initial
            else:
                pass
            if reference is not None and reference in runtime_block.in_vars:
                runtime_block.init_eqs[reference] = reference_initial
            else:
                pass
        else:
            pass
        return composite_template
    else:
        return None


