def set_exc_rexs_feedback_selector(
        cgmes_object: ExcREXS,
        template: RmsModelTemplate,
        variable_factory: VarFactory,
) -> None:
    """Write the selector's RDF enumeration code into its explicit event.

    :param cgmes_object: Parsed ExcREXS object with canonical ``fbf`` enum.
    :param template: Equation graph whose selector event is updated.
    :param variable_factory: Factory used to create a graph-owned constant.
    :return: None.
    """
    feedback_value: object = cgmes_object.get_declared_property_value('fbf')
    if feedback_value == ExcREXSFeedbackSignalKind.fieldCurrent:
        feedback_code: float = 1.0
    elif feedback_value == ExcREXSFeedbackSignalKind.outputVoltage:
        feedback_code = 2.0
    elif feedback_value is None or feedback_value == ExcREXSFeedbackSignalKind.fieldVoltage:
        feedback_code = 0.0
    else:
        feedback_code = -1.0
    for runtime_block in template.block.get_all_blocks():
        for parameter_variable in runtime_block.event_dict:
            if parameter_variable.name == f'ExcREXS.fbf_{template.name}':
                runtime_block.event_dict[parameter_variable] = variable_factory.add_const(
                    value=feedback_code,
                    name=parameter_variable.name,
                )
            else:
                pass
    else:
        pass


