def get_gov_hydro1_parameters(cgmes_object: Base) -> GovHydro1Parameters:
    """Map the GovHydro1 scalar RDF values into its equation settings.

    :param cgmes_object: Parsed GovHydro1 Dynamics record.
    :return: Equation settings with source values or standard defaults.
    """
    defaults: GovHydro1Parameters = GovHydro1Parameters()
    mwbase: float = get_turbine_governor_power_base(cgmes_object) or defaults.mwbase
    dturb_raw: float = get_cgmes_numeric_or_default(
        cgmes_object, 'dturb', defaults.dturb,
    )
    machine_mva_base: float | None = None
    machine_dynamics: object = cgmes_object.get_declared_property_value(
        'SynchronousMachineDynamics'
    )
    if isinstance(machine_dynamics, SynchronousMachineDynamics):
        machine: object = machine_dynamics.SynchronousMachine
        if isinstance(machine, Base):
            machine_mva_base = get_numeric_parameter_value(
                machine.get_declared_property_value('ratedS')
            )
        else:
            pass
    elif "AsynchronousMachineDynamics" in cgmes_object.get_declared_property_names():
        asynchronous_dynamics: object = cgmes_object.get_declared_property_value(
            'AsynchronousMachineDynamics'
        )
        if isinstance(asynchronous_dynamics, AsynchronousMachineDynamics):
            asynchronous_bases: tuple[float, float] | None = get_asynchronous_machine_power_bases(
                asynchronous_dynamics
            )
            if asynchronous_bases is not None:
                machine_mva_base = asynchronous_bases[0]
            else:
                pass
        else:
            pass
    else:
        pass
    if (
            machine_mva_base is not None
            and machine_mva_base > 0.0
            and mwbase > 0.0
    ):
        dturb_equation: float = dturb_raw * machine_mva_base / mwbase
    else:
        dturb_equation = dturb_raw
    return GovHydro1Parameters(
        mwbase=mwbase,
        rperm=get_cgmes_numeric_or_default(cgmes_object, 'rperm', defaults.rperm),
        rtemp=get_cgmes_numeric_or_default(cgmes_object, 'rtemp', defaults.rtemp),
        tr=get_cgmes_numeric_or_default(cgmes_object, 'tr', defaults.tr),
        tf=get_cgmes_numeric_or_default(cgmes_object, 'tf', defaults.tf),
        tg=get_cgmes_numeric_or_default(cgmes_object, 'tg', defaults.tg),
        velm=get_cgmes_numeric_or_default(cgmes_object, 'velm', defaults.velm),
        gmax=get_cgmes_numeric_or_default(cgmes_object, 'gmax', defaults.gmax),
        gmin=get_cgmes_numeric_or_default(cgmes_object, 'gmin', defaults.gmin),
        tw=get_cgmes_numeric_or_default(cgmes_object, 'tw', defaults.tw),
        at=get_cgmes_numeric_or_default(cgmes_object, 'at', defaults.at),
        dturb=dturb_equation,
        qnl=get_cgmes_numeric_or_default(cgmes_object, 'qnl', defaults.qnl),
        hdam=get_cgmes_numeric_or_default(cgmes_object, 'hdam', defaults.hdam),
    )


