def get_gov_hydro4_turbine_kind(cgmes_object: Base) -> GovHydro4TurbineKind:
    """Resolve the turbine variant from its RDF selector or canonical parameter set.

    :param cgmes_object: Parsed CGMES 2.4.15 or 2020 GovHydro4 record.
    :return: Variant selected by the explicit 2020 enum or the 2.4.15 EA field rules.
    """
    if isinstance(cgmes_object, GovHydro424):
        blade_adjustment: float = get_cgmes_numeric_or_default(
            cgmes_object, 'bmax', 0.0,
        )
        blade_points: tuple[float, float, float, float, float, float] = (
            get_cgmes_numeric_or_default(cgmes_object, 'bgv0', 0.0),
            get_cgmes_numeric_or_default(cgmes_object, 'bgv1', 0.0),
            get_cgmes_numeric_or_default(cgmes_object, 'bgv2', 0.0),
            get_cgmes_numeric_or_default(cgmes_object, 'bgv3', 0.0),
            get_cgmes_numeric_or_default(cgmes_object, 'bgv4', 0.0),
            get_cgmes_numeric_or_default(cgmes_object, 'bgv5', 0.0),
        )
        if blade_adjustment != 0.0 or any(value != 0.0 for value in blade_points):
            model_kind: GovHydro4TurbineKind = GovHydro4TurbineKind.kaplan
        elif cgmes_object.gv0 is None:
            model_kind = GovHydro4TurbineKind.simple
        else:
            model_kind = GovHydro4TurbineKind.francis_pelton
    else:
        rdf_model: object = cgmes_object.get_declared_property_value('model')
        if rdf_model == GovHydro4ModelKind.francisPelton:
            model_kind = GovHydro4TurbineKind.francis_pelton
        elif rdf_model == GovHydro4ModelKind.kaplan:
            model_kind = GovHydro4TurbineKind.kaplan
        else:
            model_kind = GovHydro4TurbineKind.simple
    return model_kind


