def get_gov_steam1_settings(cgmes_object: Base) -> GovSteam1Settings:
    """Build GovSteam1 topology and curve settings from imported RDF values.

    :param cgmes_object: Parsed GovSteam1 dynamics object.
    :return: Stage times, valve selector, and six gate/power points.
    """
    times: tuple[float, float, float, float, float, float, float] = (
        get_cgmes_numeric_or_default(cgmes_object, "t1", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "t2", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "t3", 0.1),
        get_cgmes_numeric_or_default(cgmes_object, "t4", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "t5", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "t6", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "t7", 0.0),
    )
    gv_points: tuple[float, float, float, float, float, float] = (
        get_cgmes_numeric_or_default(cgmes_object, "gv1", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "gv2", 0.2),
        get_cgmes_numeric_or_default(cgmes_object, "gv3", 0.4),
        get_cgmes_numeric_or_default(cgmes_object, "gv4", 0.6),
        get_cgmes_numeric_or_default(cgmes_object, "gv5", 0.8),
        get_cgmes_numeric_or_default(cgmes_object, "gv6", 1.0),
    )
    pgv_points: tuple[float, float, float, float, float, float] = (
        get_cgmes_numeric_or_default(cgmes_object, "pgv1", 0.0),
        get_cgmes_numeric_or_default(cgmes_object, "pgv2", 0.2),
        get_cgmes_numeric_or_default(cgmes_object, "pgv3", 0.4),
        get_cgmes_numeric_or_default(cgmes_object, "pgv4", 0.6),
        get_cgmes_numeric_or_default(cgmes_object, "pgv5", 0.8),
        get_cgmes_numeric_or_default(cgmes_object, "pgv6", 1.0),
    )
    valve_value: float = get_cgmes_numeric_or_default(cgmes_object, "valve", 1.0)
    return GovSteam1Settings(
        times=times,
        valve=valve_value != 0.0,
        gv_points=gv_points,
        pgv_points=pgv_points,
    )


