def get_gov_steam_f_v3_parameters(cgmes_object: Base) -> GovSteamFV3Parameters:
    """Map the canonical GovSteamFV3 scalar fields into its equations.

    :param cgmes_object: Parsed GovSteamFV3 Dynamics object.
    :return: Settings containing all RDF coefficients and curve points.
    """
    defaults: GovSteamFV3Parameters = GovSteamFV3Parameters()
    if isinstance(cgmes_object, GovSteamFV324):
        # The 2.4.15 EA says the intercept-valve characteristic is built in;
        # IEC 61970-302:2023 Table 131 supplies its typical five-point curve.
        curve_values: tuple[float, ...] = (
            0.0, 0.0,
            0.4, 0.75,
            0.5, 0.91,
            0.6, 0.98,
            1.0, 1.0,
            1.25, 1.0,
        )
    else:
        curve_values = (
            get_cgmes_numeric_or_default(cgmes_object, 'gv1', defaults.gv1),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv1', defaults.pgv1),
            get_cgmes_numeric_or_default(cgmes_object, 'gv2', defaults.gv2),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv2', defaults.pgv2),
            get_cgmes_numeric_or_default(cgmes_object, 'gv3', defaults.gv3),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv3', defaults.pgv3),
            get_cgmes_numeric_or_default(cgmes_object, 'gv4', defaults.gv4),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv4', defaults.pgv4),
            get_cgmes_numeric_or_default(cgmes_object, 'gv5', defaults.gv5),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv5', defaults.pgv5),
            get_cgmes_numeric_or_default(cgmes_object, 'gv6', defaults.gv6),
            get_cgmes_numeric_or_default(cgmes_object, 'pgv6', defaults.pgv6),
        )
    return GovSteamFV3Parameters(
        mwbase=get_cgmes_numeric_or_default(cgmes_object, 'mwbase', defaults.mwbase),
        k=get_cgmes_numeric_or_default(cgmes_object, 'k', defaults.k),
        t1=get_cgmes_numeric_or_default(cgmes_object, 't1', defaults.t1),
        t2=get_cgmes_numeric_or_default(cgmes_object, 't2', defaults.t2),
        t3=get_cgmes_numeric_or_default(cgmes_object, 't3', defaults.t3),
        uo=get_cgmes_numeric_or_default(cgmes_object, 'uo', defaults.uo),
        uc=get_cgmes_numeric_or_default(cgmes_object, 'uc', defaults.uc),
        pmax=get_cgmes_numeric_or_default(cgmes_object, 'pmax', defaults.pmax),
        pmin=get_cgmes_numeric_or_default(cgmes_object, 'pmin', defaults.pmin),
        t4=get_cgmes_numeric_or_default(cgmes_object, 't4', defaults.t4),
        k1=get_cgmes_numeric_or_default(cgmes_object, 'k1', defaults.k1),
        t5=get_cgmes_numeric_or_default(cgmes_object, 't5', defaults.t5),
        k2=get_cgmes_numeric_or_default(cgmes_object, 'k2', defaults.k2),
        t6=get_cgmes_numeric_or_default(cgmes_object, 't6', defaults.t6),
        k3=get_cgmes_numeric_or_default(cgmes_object, 'k3', defaults.k3),
        ta=get_cgmes_numeric_or_default(cgmes_object, 'ta', defaults.ta),
        tb=get_cgmes_numeric_or_default(cgmes_object, 'tb', defaults.tb),
        tc=get_cgmes_numeric_or_default(cgmes_object, 'tc', defaults.tc),
        prmax=get_cgmes_numeric_or_default(cgmes_object, 'prmax', defaults.prmax),
        gv1=curve_values[0],
        pgv1=curve_values[1],
        gv2=curve_values[2],
        pgv2=curve_values[3],
        gv3=curve_values[4],
        pgv3=curve_values[5],
        gv4=curve_values[6],
        pgv4=curve_values[7],
        gv5=curve_values[8],
        pgv5=curve_values[9],
        gv6=curve_values[10],
        pgv6=curve_values[11],
    )


