def get_gov_steam_ieee1_parameters(cgmes_object: Base) -> MultiStageSteamGovernorParameters:
    """Map CGMES GovSteamIEEE1 fields to VeraGrid's IEEE G1 equations.

    :param cgmes_object: Parsed GovSteamIEEE1 dynamics object.
    :return: Native IEEE G1 parameter set populated from the RDF scalar values.
    """
    defaults: MultiStageSteamGovernorParameters = MultiStageSteamGovernorParameters()
    turbine_times: tuple[float, float, float, float] = (
        get_cgmes_numeric_or_default(cgmes_object, "t4", defaults.turbine_times[0]),
        get_cgmes_numeric_or_default(cgmes_object, "t5", defaults.turbine_times[1]),
        get_cgmes_numeric_or_default(cgmes_object, "t6", defaults.turbine_times[2]),
        get_cgmes_numeric_or_default(cgmes_object, "t7", defaults.turbine_times[3]),
    )
    fractions: tuple[float, float, float, float, float, float, float, float] = (
        get_cgmes_numeric_or_default(cgmes_object, "k1", defaults.fractions[0]),
        get_cgmes_numeric_or_default(cgmes_object, "k2", defaults.fractions[1]),
        get_cgmes_numeric_or_default(cgmes_object, "k3", defaults.fractions[2]),
        get_cgmes_numeric_or_default(cgmes_object, "k4", defaults.fractions[3]),
        get_cgmes_numeric_or_default(cgmes_object, "k5", defaults.fractions[4]),
        get_cgmes_numeric_or_default(cgmes_object, "k6", defaults.fractions[5]),
        get_cgmes_numeric_or_default(cgmes_object, "k7", defaults.fractions[6]),
        get_cgmes_numeric_or_default(cgmes_object, "k8", defaults.fractions[7]),
    )
    return MultiStageSteamGovernorParameters(
        gain=get_cgmes_numeric_or_default(cgmes_object, "k", defaults.gain),
        speed_lag=get_cgmes_numeric_or_default(cgmes_object, "t1", defaults.speed_lag),
        speed_lead=get_cgmes_numeric_or_default(cgmes_object, "t2", defaults.speed_lead),
        servo_time=get_cgmes_numeric_or_default(cgmes_object, "t3", defaults.servo_time),
        opening_rate=get_cgmes_numeric_or_default(cgmes_object, "uo", defaults.opening_rate),
        closing_rate=get_cgmes_numeric_or_default(cgmes_object, "uc", defaults.closing_rate),
        maximum=get_cgmes_numeric_or_default(cgmes_object, "pmax", defaults.maximum),
        minimum=get_cgmes_numeric_or_default(cgmes_object, "pmin", defaults.minimum),
        turbine_times=turbine_times,
        fractions=fractions,
    )


def initialize_governor_power_reference(
        cgmes_object: Base,
        template: RmsModelTemplate,
        attached_device: object,
        variable_factory: VarFactory,
        logger: DataLogger,
        nominal_frequency: float = 50.0,
        operating_power_mw: float | None = None,
        operating_speed_pu: float = 1.0,
        operating_electrical_power_mw: float | None = None,
) -> None:
    """Seed a turbine governor reference from its generator operating point.

    :param cgmes_object: Parsed turbine governor record carrying MWBASE.
    :param template: Built governor model whose reference input needs its equilibrium seed.
    :param attached_device: Converted physical generator associated through CGMES.
    :param variable_factory: Factory owning the template's symbolic constants.
    :param logger: Import logger for missing base or model input.
    :param nominal_frequency: Circuit frequency in Hz for frequency deadbands.
    :param operating_power_mw: Optional loss-adjusted mechanical power in MW.
    :param operating_speed_pu: Operating rotor speed for droop reference compensation.
    :param operating_electrical_power_mw: Optional machine electrical active power in MW.
    :return: None.
    """
    if isinstance(attached_device, Generator):
        solved_generator_power_mw: float = (
            float(attached_device.P) if operating_power_mw is None else operating_power_mw
        )
        power_base: float | None = get_turbine_governor_power_base(cgmes_object)
        if power_base is not None and power_base > 0.0:
            gov_hydro3_blocks: List[Block] = list()
            if cgmes_object.__class__.__name__ == "GovHydro3":
                for model_block in template.block.get_all_blocks():
                    if any(
                            variable.name.startswith('GateOpeningPu_')
                            for variable in model_block.algebraic_vars
                    ):
                        gov_hydro3_blocks.append(model_block)
                    else:
                        pass
            else:
                pass
            reference_ports: List[Tuple[Block, Var]] = list()
            speed_reference_ports: List[Tuple[Block, Var]] = list()
            for model_block in template.block.get_all_blocks():
                for input_variable in model_block.in_vars:
                    if (
                            input_variable.name.startswith("PRefPu_")
                            or input_variable.name.startswith("ReferencePu_")
                            or input_variable.name.startswith("PmRefPu_")
                            or input_variable.name.startswith("gov.PmRefPu_")
                            or input_variable.name.startswith("gov.PRefPu_")
                    ):
                        reference_ports.append((model_block, input_variable))
                    elif input_variable.name.startswith("gov.omegaRefPu_"):
                        speed_reference_ports.append((model_block, input_variable))
                    else:
                        pass
            if len(reference_ports) == 0:
                reference_ports = speed_reference_ports
            else:
                pass
            if len(gov_hydro3_blocks) == 1 and cgmes_object.__class__.__name__ == "GovHydro3":
                reference_block: Block = gov_hydro3_blocks[0]
                reference_port: Var = reference_block.in_vars[1]
                reference_pu: float = solved_generator_power_mw / power_base
                hydro3: GovHydro3Parameters = get_gov_hydro3_parameters(
                    cgmes_object, nominal_frequency,
                )
                electrical_power_mw: float = float(attached_device.P)
                speed_deviation_pu: float = operating_speed_pu - 1.0
                speed_threshold_pu: float = hydro3.db1 / hydro3.nominal_frequency
                speed_pickup_pu: float = (
                    hydro3.db1 + hydro3.eps
                ) / hydro3.nominal_frequency
                if speed_deviation_pu > speed_pickup_pu:
                    active_deadband_speed_pu: float = (
                        speed_deviation_pu - speed_threshold_pu
                    )
                elif speed_deviation_pu < -speed_pickup_pu:
                    active_deadband_speed_pu = speed_deviation_pu + speed_threshold_pu
                else:
                    active_deadband_speed_pu = 0.0
                if hydro3.governor_control:
                    reference_deadband_speed_pu: float = active_deadband_speed_pu
                else:
                    reference_deadband_speed_pu = 0.0
                required_curve_power: float = (
                    solved_generator_power_mw / hydro3.mwbase / hydro3.at
                    + hydro3.qnl
                    + hydro3.dturb * speed_deviation_pu / hydro3.at
                    + hydro3.h0 - 1.0
                )
                hydro3_gate: float | None = get_gov_hydro3_gate_for_power(
                    hydro3, required_curve_power,
                )
                if hydro3_gate is not None:
                    reference_pu = hydro3_gate * hydro3.rgate + (
                        electrical_power_mw / hydro3.mwbase
                    ) * hydro3.relec + reference_deadband_speed_pu
                else:
                    logger.add_warning(
                        msg="CGMES GovHydro3 turbine curve cannot be inverted at generator operating power",
                        device=cgmes_object.rdfid,
                        device_class=cgmes_object.__class__.__name__,
                    )
                reference_block.init_eqs[reference_port] = variable_factory.add_const(
                    value=reference_pu,
                    name=reference_port.name,
                )
                for mode_variable in reference_block.mode_dict:
                    if mode_variable.name.startswith('PositiveSpeedDeadbandMode_'):
                        mode_value: float = float(speed_deviation_pu > speed_pickup_pu)
                        reference_block.mode_dict[mode_variable] = variable_factory.add_const(
                            value=mode_value,
                            name=mode_variable.name,
                        )
                    elif mode_variable.name.startswith('NegativeSpeedDeadbandMode_'):
                        mode_value = float(speed_deviation_pu < -speed_pickup_pu)
                        reference_block.mode_dict[mode_variable] = variable_factory.add_const(
                            value=mode_value,
                            name=mode_variable.name,
                        )
                    else:
                        pass
                if hydro3_gate is not None:
                    for initial_variable in reference_block.init_eqs:
                        variable_name: str = initial_variable.name
                        if variable_name.startswith((
                                'GateOpeningPu_', 'GovernorGateCommandPu_',
                                'MechanicalGovernorCommandPu_', 'GovernorIntegralPu_',
                        )):
                            initial_value: float = hydro3_gate
                        elif variable_name.startswith('CurvePowerPu_'):
                            initial_value = get_gov_hydro3_curve_power(hydro3, hydro3_gate)
                        elif variable_name.startswith('SpeedDeviationPu_'):
                            initial_value = speed_deviation_pu
                        elif variable_name.startswith('SpeedDerivativeFilterPu_'):
                            initial_value = active_deadband_speed_pu
                        elif variable_name.startswith('FilteredElectricalPowerPu_'):
                            initial_value = electrical_power_mw / hydro3.mwbase
                        elif variable_name.startswith('TurbineHeadPu_'):
                            initial_value = 1.0
                        elif variable_name.startswith((
                                'TurbineFlowPu_', 'WaterColumnMemoryPu_',
                        )):
                            initial_value = hydro3_gate
                        elif variable_name.startswith('PmPu_'):
                            initial_value = solved_generator_power_mw / hydro3.mwbase
                        else:
                            initial_value = 0.0
                        if variable_name.startswith((
                                'GateOpeningPu_', 'GovernorGateCommandPu_',
                                'MechanicalGovernorCommandPu_', 'GovernorIntegralPu_',
                                'CurvePowerPu_', 'FilteredElectricalPowerPu_',
                                'SpeedDeviationPu_',
                                'SpeedDerivativeFilterPu_',
                                'TurbineHeadPu_', 'TurbineFlowPu_',
                                'WaterColumnMemoryPu_', 'PmPu_',
                        )):
                            reference_block.init_eqs[initial_variable] = variable_factory.add_const(
                                value=initial_value,
                                name=variable_name,
                            )
                        else:
                            pass
                else:
                    pass
            elif len(reference_ports) == 1:
                reference_block: Block = reference_ports[0][0]
                reference_port: Var = reference_ports[0][1]
                reference_pu: float = solved_generator_power_mw / power_base
                if cgmes_object.__class__.__name__ == "GovSteam2":
                    steam2_gain: float = get_cgmes_numeric_or_default(
                        cgmes_object, 'k', 20.0,
                    )
                    steam2_deadband: float = get_cgmes_numeric_or_default(
                        cgmes_object, 'dbf', 0.0,
                    )
                    steam2_speed_error: float = 1.0 - operating_speed_pu
                    steam2_half_deadband: float = steam2_deadband / 2.0
                    steam2_deadband_output: float = (
                        max(steam2_speed_error - steam2_half_deadband, 0.0)
                        + min(steam2_speed_error + steam2_half_deadband, 0.0)
                    )
                    steam2_speed_correction: float = min(
                        max(
                            steam2_gain * steam2_deadband_output,
                            get_cgmes_numeric_or_default(cgmes_object, 'mnef', -1.0),
                        ),
                        get_cgmes_numeric_or_default(cgmes_object, 'mxef', 1.0),
                    )
                    reference_pu -= steam2_speed_correction
                elif cgmes_object.__class__.__name__ == "GovGAST":
                    gast: GasGovernorParameters = get_gast_parameters(cgmes_object)
                    speed_deviation: float = operating_speed_pu - 1.0
                    reference_pu += speed_deviation / gast.r + gast.damping * speed_deviation
                elif cgmes_object.__class__.__name__ == "GovSteamFV2":
                    fv2: GovSteamFV2Parameters = get_gov_steam_f_v2_parameters(cgmes_object)
                    # The turbine path must offset its explicit speed-damping term before
                    # the droop reference is chosen at an induction-machine operating speed.
                    operating_power: float = solved_generator_power_mw / fv2.mwbase
                    fv2_turbine_power: float = (
                        operating_power - fv2.dt * (1.0 - operating_speed_pu)
                    )
                    reference_pu = operating_speed_pu + fv2.r * fv2_turbine_power
                    reheater_power: float = (1.0 - fv2.k) * fv2_turbine_power
                    for initial_variable in reference_block.init_eqs:
                        variable_name: str = initial_variable.name
                        if variable_name.startswith('GovSteamFV2ValveCommandPu_'):
                            initial_value: float = fv2_turbine_power
                            has_initial_value: bool = True
                        elif variable_name.startswith((
                                'GovSteamFV2ReheaterPowerPu_',
                                'GovSteamFV2InterceptPowerPu_',
                        )):
                            initial_value = reheater_power
                            has_initial_value = True
                        elif variable_name.startswith('gov.PmPu_'):
                            initial_value = operating_power
                            has_initial_value = True
                        elif variable_name.startswith('gov.PmMW_'):
                            initial_value = solved_generator_power_mw
                            has_initial_value = True
                        else:
                            initial_value = 0.0
                            has_initial_value = False
                        if has_initial_value:
                            reference_block.init_eqs[initial_variable] = variable_factory.add_const(
                                value=initial_value,
                                name=variable_name,
                            )
                        else:
                            pass
                elif cgmes_object.__class__.__name__ == "GovSteamEU":
                    electrical_power_mw: float = (
                        float(attached_device.P)
                        if operating_electrical_power_mw is None
                        else operating_electrical_power_mw
                    )
                    reference_pu = electrical_power_mw / power_base
                    if not math.isclose(
                            solved_generator_power_mw,
                            electrical_power_mw,
                            rel_tol=1.0e-9,
                            abs_tol=1.0e-6,
                    ):
                        logger.add_warning(
                            msg=(
                                'CGMES GovSteamEU steady-state residuals assume zero generator losses '
                                '(IEC 61970-302:2023-06 §5.3.6.52 note 7); solved shaft and electrical '
                                'power differ'
                            ),
                            device=cgmes_object.rdfid,
                            device_class=cgmes_object.__class__.__name__,
                        )
                    else:
                        pass
                elif cgmes_object.__class__.__name__ == "GovSteam0":
                    steam0: GovSteam0Parameters = get_gov_steam0_parameters(cgmes_object)
                    reference_pu += (
                        (operating_speed_pu - 1.0) / steam0.r
                        + steam0.dt * (operating_speed_pu - 1.0)
                    )
                elif cgmes_object.__class__.__name__ == "GovHydroIEEE0":
                    hydro_ieee0: GovHydroIEEE0Parameters = get_gov_hydro_ieee0_parameters(
                        cgmes_object,
                    )
                    hydro_ieee0_power: float = solved_generator_power_mw / hydro_ieee0.mwbase
                    hydro_ieee0_speed_error: float = operating_speed_pu - 1.0
                    reference_pu = hydro_ieee0_power + hydro_ieee0.k * hydro_ieee0_speed_error
                    for initial_variable in reference_block.init_eqs:
                        variable_name: str = initial_variable.name
                        if variable_name.startswith((
                                'SpeedGovernorLag_', 'SpeedGovernorCompensatorState_',
                        )):
                            initial_value: float = hydro_ieee0_speed_error
                        elif variable_name.startswith((
                                'SpeedGovernorCompensator_', 'GateCommandPu_', 'PmPu_',
                                'PmPuState_',
                        )):
                            initial_value = hydro_ieee0_power
                            if variable_name.startswith('SpeedGovernorCompensator_'):
                                initial_value = hydro_ieee0_speed_error
                            else:
                                pass
                        else:
                            initial_value = 0.0
                        if variable_name.startswith((
                                'SpeedGovernorLag_', 'SpeedGovernorCompensatorState_',
                                'SpeedGovernorCompensator_', 'GateCommandPu_', 'PmPu_',
                                'PmPuState_',
                        )):
                            reference_block.init_eqs[initial_variable] = variable_factory.add_const(
                                value=initial_value,
                                name=variable_name,
                            )
                        else:
                            pass
                elif cgmes_object.__class__.__name__ == "GovSteamFV3":
                    reference_pu = solved_generator_power_mw / power_base
                elif cgmes_object.__class__.__name__ == "GovSteamSGO":
                    sgo: GovSteamSGOParameters = get_gov_steam_s_g_o_parameters(cgmes_object)
                    turbine_dc_gain: float = 3.0 - sgo.k2 - sgo.k3
                    operating_power = solved_generator_power_mw / power_base
                    if (
                            turbine_dc_gain > 0.0
                            and sgo.pmin <= operating_power <= sgo.pmax
                            and sgo.pmin <= operating_power / turbine_dc_gain <= sgo.pmax
                    ):
                        reference_pu = operating_power / turbine_dc_gain
                        sgo_turbine_input: float = reference_pu
                        sgo_reference_is_feasible: bool = True
                    else:
                        reference_pu = operating_power
                        sgo_turbine_input = operating_power
                        sgo_reference_is_feasible = False
                        logger.add_warning(
                            msg="CGMES GovSteamSGO operating power is outside its turbine or valve limits",
                            device=cgmes_object.rdfid,
                            device_class=cgmes_object.__class__.__name__,
                        )
                    if sgo_reference_is_feasible:
                        reference_block.init_eqs[reference_port] = variable_factory.add_const(
                            value=reference_pu,
                            name=reference_port.name,
                        )
                        for initial_variable in reference_block.init_eqs:
                            variable_name: str = initial_variable.name
                            if variable_name.startswith((
                                    'GovSteamSGOValvePu_', 'GovSteamSGOSteamChestPu_',
                                    'GovSteamSGOReheaterPu_', 'GovSteamSGOLowPressurePu_',
                            )):
                                initial_value = sgo_turbine_input
                                has_initial_value: bool = True
                            elif variable_name.startswith((
                                    'GovSteamSGOControllerPu_',
                            )):
                                initial_value = 0.0
                                has_initial_value = True
                            elif variable_name.startswith('GovSteamSGOReferenceSumPu_'):
                                initial_value = sgo_turbine_input
                                has_initial_value = True
                            elif variable_name.startswith(('gov.PmPu_', 'gov.PmMW_')):
                                if variable_name.startswith('gov.PmMW_'):
                                    initial_value = operating_power * power_base
                                else:
                                    initial_value = operating_power
                                has_initial_value = True
                            else:
                                initial_value = 0.0
                                has_initial_value = False
                            if has_initial_value:
                                reference_block.init_eqs[initial_variable] = variable_factory.add_const(
                                    value=initial_value,
                                    name=variable_name,
                                )
                            else:
                                pass
                    else:
                        logger.add_warning(
                            msg="CGMES GovSteamSGO solved power cannot be balanced at the imported initial speed",
                            device=cgmes_object.rdfid,
                            device_class=cgmes_object.__class__.__name__,
                        )
                elif cgmes_object.__class__.__name__ == "GovSteamFV4":
                    fv4: GovSteamFV4Parameters = get_gov_steam_f_v4_parameters(cgmes_object)
                    operating_power: float = solved_generator_power_mw / power_base
                    # Hold the speed-reference output at measured electrical power so the
                    # electro-hydraulic PI is at equilibrium at the solved rotor speed.
                    frequency_bias_initial: float = min(
                        max(fv4.kf1 * (1.0 - operating_speed_pu), fv4.lpi),
                        fv4.lps,
                    )
                    electrical_power_pu: float = float(attached_device.P) / power_base
                    reference_pu = min(
                        max(electrical_power_pu - frequency_bias_initial, fv4.crmn),
                        fv4.crmx,
                    )
                    control_valve_lower: float = fv4.yhpmn
                    control_valve_upper: float = fv4.yhpmx
                    control_valve_initial: float = min(
                        max(operating_power, control_valve_lower), control_valve_upper,
                    )
                    pressure_reference_initial: float = fv4.psmn + (1.0 - fv4.psmn) * min(
                        max((reference_pu - fv4.pr1) / (fv4.pr2 - fv4.pr1), 0.0), 1.0,
                    )
                    steam_flow_initial: float = operating_power
                    boiler_pressure_initial: float = (
                        pressure_reference_initial + fv4.ksh * steam_flow_initial ** 2
                    )
                    # Invert the Figure 84 turbine equations with Ps fixed at its setpoint.
                    if (
                            boiler_pressure_initial > 0.0
                            and 0.0 < fv4.y < 1.0
                            and 0.0 < fv4.khp < 1.0
                    ):
                        for curve_iteration in range(48):
                            control_valve_trial: float = 0.5 * (
                                control_valve_lower + control_valve_upper
                            )
                            intercept_trial: float = (
                                0.1 + fv4.kmp1 * control_valve_trial
                                + (fv4.kmp2 - fv4.kmp1)
                                * max(control_valve_trial - fv4.srsmp, 0.0)
                            )
                            intercept_trial = min(
                                max(intercept_trial, fv4.ympmn), fv4.ympmx,
                            )
                            hp_power_trial: float = (
                                pressure_reference_initial * control_valve_trial
                            )
                            reheater_power_trial: float = (
                                hp_power_trial / (fv4.y * (2.0 - fv4.y))
                            )
                            reheater_flow_trial: float = (
                                reheater_power_trial * intercept_trial
                            )
                            turbine_power_trial: float = (
                                fv4.khp * hp_power_trial
                                + (1.0 - fv4.khp) * reheater_flow_trial
                            )
                            if turbine_power_trial < operating_power:
                                control_valve_lower = control_valve_trial
                            else:
                                control_valve_upper = control_valve_trial
                        control_valve_initial = 0.5 * (
                            control_valve_lower + control_valve_upper
                        )
                    else:
                        pass
                    intercept_characteristic: float = (
                        0.1 + fv4.kmp1 * control_valve_initial
                        + (fv4.kmp2 - fv4.kmp1)
                        * max(control_valve_initial - fv4.srsmp, 0.0)
                    )
                    intercept_valve_initial: float = min(
                        max(intercept_characteristic, fv4.ympmn), fv4.ympmx,
                    )
                    high_pressure_flow_initial: float = (
                        control_valve_initial * pressure_reference_initial
                    )
                    reheater_power_initial: float = (
                        high_pressure_flow_initial / (fv4.y * (2.0 - fv4.y))
                    )
                    steam_flow_initial = fv4.y * reheater_power_initial
                    boiler_pressure_initial = (
                        pressure_reference_initial + fv4.ksh * steam_flow_initial ** 2
                    )
                    electro_servo_initial: float = min(max(1.0, fv4.srmn), fv4.srmx)
                    electro_output_initial: float = 0.0
                    electro_integral_initial: float = 0.0
                    frequency_correction_initial: float = min(
                        max(fv4.kf3 * (1.0 - operating_speed_pu), fv4.mnef),
                        fv4.mxef,
                    )
                    electro_control_initial: float = (
                        electro_servo_initial + frequency_correction_initial
                    )
                    fuel_regulator_initial: float = min(
                        max(steam_flow_initial, fv4.crmn), fv4.crmx,
                    )
                    valve_pressure_integral_initial: float = min(
                        max(control_valve_initial, fv4.rsmimn), fv4.rsmimx,
                    )
                    if abs(electro_control_initial) > 1.0e-12:
                        pressure_integral_demand: float = (
                            (steam_flow_initial - 1.0) / electro_control_initial
                            - frequency_bias_initial
                        )
                    else:
                        pressure_integral_demand = steam_flow_initial - 1.0
                    pressure_integral_initial: float = min(
                        max(pressure_integral_demand, fv4.cpsmn), fv4.cpsmx,
                    )
                    low_pressure_state_initial: float = (
                        reheater_power_initial * intercept_valve_initial
                    )
                    turbine_power_initial: float = (
                        fv4.khp * high_pressure_flow_initial
                        + (1.0 - fv4.khp) * low_pressure_state_initial
                    )
                    if not (
                            pressure_integral_initial == pressure_integral_demand
                            and fuel_regulator_initial == steam_flow_initial
                            and valve_pressure_integral_initial == control_valve_initial
                            and fv4.rsmimn <= control_valve_initial <= fv4.rsmimx
                            and fv4.srmn <= 1.0 <= fv4.srmx
                            and math.isclose(
                                turbine_power_initial,
                                operating_power,
                                rel_tol=1e-9,
                                abs_tol=1e-9,
                            )
                    ):
                        logger.add_warning(
                            msg=(
                                'CGMES GovSteamFV4 bounds cannot reproduce the solved '
                                'generator operating point with its Figure 84 steady state'
                            ),
                            device=cgmes_object.rdfid,
                            device_class=cgmes_object.__class__.__name__,
                        )
                    else:
                        pass
                    for initial_variable in reference_block.init_eqs:
                        variable_name: str = initial_variable.name
                        if variable_name.startswith((
                                'GovSteamFV4ControlValvePu_',
                        )):
                            initial_value = control_valve_initial
                        elif variable_name.startswith('GovSteamFV4FuelRegulatorPu_'):
                            initial_value = fuel_regulator_initial
                        elif variable_name.startswith('GovSteamFV4RegulatorReferencePu_'):
                            initial_value = min(
                                max(reference_pu + frequency_bias_initial, fv4.crmn),
                                fv4.crmx,
                            )
                        elif variable_name.startswith('GovSteamFV4ValvePressureIntegralPu_'):
                            initial_value = valve_pressure_integral_initial
                        elif variable_name.startswith('GovSteamFV4ValvePressureReferencePu_'):
                            initial_value = control_valve_initial
                        elif variable_name.startswith('GovSteamFV4PressureIntegralPu_'):
                            initial_value = pressure_integral_initial
                        elif variable_name.startswith((
                                'GovSteamFV4PressureDerivativePu_',
                                'GovSteamFV4PressureDerivativeFilterPu_',
                        )):
                            initial_value = 0.0
                        elif variable_name.startswith('GovSteamFV4PressureControllerPu_'):
                            initial_value = pressure_integral_initial
                        elif variable_name.startswith('GovSteamFV4ElectroHydraulicIntegralPu_'):
                            initial_value = electro_integral_initial
