def get_exc_cz_parameters(cgmes_object: Base) -> ExcCZParameters | None:
    """Map a complete numeric parameter record for canonical ExcCZ.

    :param cgmes_object: Parsed canonical ExcCZ record.
    :return: Complete PI, amplifier, and exciter settings, or None when any
        required equation parameter is absent.
    """
    kp: float | None = get_numeric_parameter_value(cgmes_object.kp)
    tc: float | None = get_numeric_parameter_value(cgmes_object.tc)
    vrmax: float | None = get_numeric_parameter_value(cgmes_object.vrmax)
    vrmin: float | None = get_numeric_parameter_value(cgmes_object.vrmin)
    ka: float | None = get_numeric_parameter_value(cgmes_object.ka)
    ta: float | None = get_numeric_parameter_value(cgmes_object.ta)
    ke: float | None = get_numeric_parameter_value(cgmes_object.ke)
    te: float | None = get_numeric_parameter_value(cgmes_object.te)
    efdmax: float | None = get_numeric_parameter_value(cgmes_object.efdmax)
    efdmin: float | None = get_numeric_parameter_value(cgmes_object.efdmin)
    if any(value is None for value in (
            kp, tc, vrmax, vrmin, ka, ta, ke, te, efdmax, efdmin,
    )):
        return None
    else:
        pass

    return ExcCZParameters(
        kp=kp,
        tc=tc,
        vrmax=vrmax,
        vrmin=vrmin,
        ka=ka,
        ta=ta,
        ke=ke,
        te=te,
        efdmax=efdmax,
        efdmin=efdmin,
    )


